package com.asterfinancials.app;
import android.app.Activity;import android.os.Bundle;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import android.graphics.Color;import java.io.ByteArrayOutputStream;import java.io.InputStream;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity{
 private String readAsset(String name)throws Exception{try(InputStream in=getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString(StandardCharsets.UTF_8.name());}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(5,6,6));getWindow().setNavigationBarColor(Color.rgb(5,6,6));WebView w=new WebView(this);w.setBackgroundColor(Color.rgb(5,6,6));w.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String u){super.onPageFinished(v,u);try{v.evaluateJavascript(readAsset("app-polish-v23.js"),null);v.evaluateJavascript(readAsset("app-navigation-v23.js"),null);v.evaluateJavascript(readAsset("app-polish-v24.js"),null);v.evaluateJavascript(readAsset("markets-v25.js"),null);v.evaluateJavascript(readAsset("markets-v26.js"),null);v.evaluateJavascript(readAsset("markets-v27.js"),null);}catch(Exception ignored){}}});WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);w.loadUrl("file:///android_asset/index.html");setContentView(w);}
}
